import {radarSources,radarCheckedAt} from './data/radar-sources.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp=s=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'尚未采集';
export function makeRadarDraft(post){
 return `# CoVibe 攻略提纲：${post.category}\n\n状态：素材提纲，未核验、未实测、未发布。此提纲由规则整理，不调用付费生成模型。\n\n## 信息来源\n- 原帖：${post.url}\n- 作者：@${post.author}\n- 发布时间：${post.publishedAt}\n- 采集时间：${post.collectedAt}\n\n## 待核验的原帖摘录\n> ${post.text.replace(/\n/g,'\n> ')}\n\n## 任务与适用范围\n[补充具体使用场景、输入素材与预期结果]\n\n## 模型与渠道\n[核对完整模型版本、渠道域名及 API 模型 ID；不得用模型系列名代替版本]\n\n## 官方依据与费用\n[补充官方文档、价格接口、免费额度条件、到期时间及核验日期]\n\n## 操作步骤\n1. [账号与环境准备]\n2. [最小可运行示例]\n3. [参数、输出检查与常见错误]\n\n## 复现记录\n尚未实测；实际费用、成功率及使用限制均待记录。\n\n## 发布前检查\n核验原帖声明、补充来源、删除占位内容；仅在实际运行后标记“已复现”。\n`;
}
export function radarHome(){return `<section class="section"><div class="section-head"><div><span class="eyebrow">SIGNALS → COVIBE</span><h2>追踪新信息，沉淀使用经验。</h2><p>X 模型动态、渠道更新与限免线索，带着来源进入 CoVibe。</p></div><a class="text-link" href="#radar" data-route="radar">查看 AI 动态 →</a></div><div class="radar-home-strip"><span>Apify 免费额度接入</span><span>每日增量 · 原帖溯源</span><span>攻略提纲 · 核验后发布</span></div></section>`;}
export function radarPage(){return `<div class="page" id="radarRoot"><div class="discovery-heading"><span class="eyebrow">VIBEBASE SIGNALS</span><h1>AI 动态</h1><p>关注模型、渠道与使用方法。把值得验证的新信息，变成下一篇 CoVibe 经验。</p></div><div class="radar-toolbar"><a class="tool-link" href="#covibe" data-route="covibe">CoVibe 经验库 →</a><a class="tool-link" href="#radar/sources" data-route="radar/sources">免费采集方案与接入状态 →</a><button class="soft-btn" id="radarRefresh">刷新记录</button></div><p id="radarStatus" class="notice" role="status">正在读取采集状态…</p><div class="radar-toolbar"><label>筛选类别<select id="radarCategory"><option>全部</option><option>模型与渠道</option><option>免费与限免</option><option>价格变化</option><option>使用经验</option></select></label><label>搜索信息<input id="radarSearch" type="search" placeholder="模型名、渠道名、关键词"></label></div><p class="mini-meta">按原帖时间排序。X 原帖是信息线索，不代表本站已确认价格、免费资格或实测效果。</p><div class="discovery-grid two" id="radarItems"></div><section id="radarDraft" class="radar-draft" hidden><h2>CoVibe 攻略提纲</h2><p>免费规则整理，保留来源；具体使用步骤和费用需要核验后补充。下载仅保存在本机，不会自动发布。</p><label>编辑提纲<textarea id="radarDraftText" rows="18"></textarea></label><div class="radar-toolbar"><button class="soft-btn" id="radarDownload">下载 Markdown 提纲</button><button class="soft-btn" id="radarCloseDraft">收起提纲</button></div></section></div>`;}
export function radarSourcesPage(){return `<div class="page" id="radarSourceRoot"><div class="discovery-heading"><span class="eyebrow">FREE SOURCES</span><h1>从免费额度开始。</h1><p>区分每月额度、一次性试用和开源软件。资料核查：${radarCheckedAt}。</p></div><a class="text-link" href="#radar" data-route="radar">← 返回 AI 动态</a><p id="radarStatus" class="notice" role="status">正在读取接入状态…</p><div class="discovery-grid two">${radarSources.map(s=>`<article class="discovery-card"><span class="tag">${esc(s.kind)}</span><h2>${esc(s.name)}</h2><h3>${esc(s.quota)}</h3><p>${esc(s.detail)}</p><div class="discovery-card-foot"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">查看官方项目 ↗</a> · <a href="${esc(s.pricing)}" target="_blank" rel="noopener noreferrer">额度依据 ↗</a></div></article>`).join('')}</div><section class="radar-draft"><h2>本期接入方式</h2><p>Apify 每日最多运行一批，3 组查询、每组最多 15 条；每 30 分钟检查任务结果。刷新页面只读取已保存的信息，不会触发付费爬虫。</p><p>管理员需在 Cloudflare Worker 配置 APIFY_TOKEN Secret，并确认账号为 Free 计划后设置 APIFY_FREE_PLAN_CONFIRMED=true。额度与账号其他任务共享，不会自动升级或充值。</p><p>twscrape / Twikit 的本地采集文件可通过项目导入脚本接入；未运行采集前不会显示为已连接。TwitterAPI.io 仅列作试用备选，本期未启用；X 官方 API 未纳入免费方案。</p><p>本期试点 Actor 较新，尚未实测。无数据、失败记录和已识别演示数据均不会冒充真实资讯。</p></section></div>`;}
export function bindRadar(){
 const root=document.querySelector('#radarRoot, #radarSourceRoot');if(!root)return;
 let items=[];
 const status=root.querySelector('#radarStatus'),list=root.querySelector('#radarItems');
 function draw(){if(!list)return;const category=root.querySelector('#radarCategory').value,q=root.querySelector('#radarSearch').value.trim().toLowerCase();const rows=items.filter(p=>(category==='全部'||p.category===category)&&(!q||(p.text+' '+p.author).toLowerCase().includes(q)));
  list.innerHTML=rows.length?rows.map(p=>`<article class="discovery-card"><div class="discovery-card-top"><span class="tag">${esc(p.category)}</span><span class="mini-meta">${esc(stamp(p.publishedAt))}</span></div><h3>@${esc(p.author)}</h3><p class="radar-excerpt">${esc(p.text)}</p><p class="mini-meta">${esc(p.evidence)} · 采集于 ${esc(stamp(p.collectedAt))}</p><div class="discovery-card-foot"><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">阅读 X 原帖 ↗</a><button class="small-action" data-radar-draft="${esc(p.id)}">整理 CoVibe 提纲</button></div></article>`).join(''):`<p class="empty">${items.length?'没有符合筛选条件的信息。':'暂无真实采集记录。接通 Apify 后，经过格式与相关性校验的原帖会出现在这里。'}<br><a href="#radar/sources" data-route="radar/sources">查看接入状态 →</a></p>`;
 }
 async function load(){const button=root.querySelector('#radarRefresh');if(button)button.disabled=true;try{const r=await fetch('/api/radar');const d=await r.json();if(!r.ok)throw Error(d.error||'读取失败');if(!root.isConnected)return;items=d.items;status.textContent=d.collection.message+' · 最近检查：'+stamp(d.collection.lastCheckedAt);draw();}catch{if(root.isConnected){status.textContent='采集记录暂时无法读取，请稍后重试。';if(list)list.innerHTML='<p class="empty">无法连接信息服务；未展示演示数据。</p>';}}finally{if(button)button.disabled=false;}}
 root.querySelector('#radarRefresh')?.addEventListener('click',load);
 root.querySelector('#radarCategory')?.addEventListener('change',draw);root.querySelector('#radarSearch')?.addEventListener('input',draw);
 root.addEventListener('click',event=>{const b=event.target.closest('[data-radar-draft]');if(!b)return;const post=items.find(p=>p.id===b.dataset.radarDraft);if(!post)return;const area=root.querySelector('#radarDraft');area.hidden=false;root.querySelector('#radarDraftText').value=makeRadarDraft(post);area.scrollIntoView({behavior:'smooth',block:'start'});root.querySelector('#radarDraftText').focus({preventScroll:true});});
 root.querySelector('#radarCloseDraft')?.addEventListener('click',()=>{root.querySelector('#radarDraft').hidden=true;});
 root.querySelector('#radarDownload')?.addEventListener('click',()=>{const blob=new Blob([root.querySelector('#radarDraftText').value],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='covibe-draft.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 load();
}
